sys_script_include.script:
var UpdateFieldAjax = Class.create();
UpdateFieldAjax.prototype = Object.extendsObject(AbstractAjaxProcessor, {
  updateField: function() {
    var sysId = this.getParameter('sysparm_sys_id');
    var newValue = "Updated Value"; // 替换为实际值

    var gr = new GlideRecord('sc_req_item'); // Catalog Item表（根据实际表调整）
    if (gr.get(sysId)) {
      gr.setValue('comments', newValue); // 更新字段（例如comments）
      return gr.update();
    }
    return false;
  },
  type: 'UpdateFieldAjax'
});
